/** US-15's local editor document. No DB, authorization or cross-domain service calls.
 * This is a C-owned candidate document format, NOT a frozen persistence/API envelope.
 * Limits are technical bounds for this editor; align them with B before API integration.
 */
import { z } from 'zod'

export const UML_EDITOR_LIMITS = { nodes: 100, edges: 300, text: 200 } as const
const id = z.string().min(1).max(64)
const name = z.string().trim().min(1, '请输入名称').max(UML_EDITOR_LIMITS.text)
const node = z.object({ id, name }).strict()
export const useCaseRelationTypes = ['ASSOCIATION', 'INCLUDE', 'EXTEND'] as const
export const sequenceMessageTypes = ['sync', 'async', 'return'] as const

const useCaseSchema = z.object({
  formatVersion: z.literal(1),
  kind: z.literal('USE_CASE'),
  actors: z.array(node).max(UML_EDITOR_LIMITS.nodes),
  useCases: z.array(node).max(UML_EDITOR_LIMITS.nodes),
  relations: z.array(z.object({
    id, type: z.enum(useCaseRelationTypes), fromId: id, toId: id,
  }).strict()).max(UML_EDITOR_LIMITS.edges),
}).strict()
const sequenceSchema = z.object({
  formatVersion: z.literal(1),
  kind: z.literal('SEQUENCE'),
  lifelines: z.array(node).max(UML_EDITOR_LIMITS.nodes),
  messages: z.array(z.object({
    id, fromId: id, toId: id, label: name,
    kind: z.enum(sequenceMessageTypes), seq: z.number().int().positive(),
  }).strict()).max(UML_EDITOR_LIMITS.edges),
}).strict()

export type UseCaseDocument = z.infer<typeof useCaseSchema>
export type SequenceDocument = z.infer<typeof sequenceSchema>
export type UmlDocument = UseCaseDocument | SequenceDocument
export type UseCaseRelation = UseCaseDocument['relations'][number]
export type SequenceMessage = SequenceDocument['messages'][number]

/** Node ids and edge ids share a single namespace inside a document. */
export const umlDocumentSchema = z.discriminatedUnion('kind', [useCaseSchema, sequenceSchema])
  .superRefine((doc, ctx) => {
    const nodes = doc.kind === 'USE_CASE' ? [...doc.actors, ...doc.useCases] : doc.lifelines
    const edges = doc.kind === 'USE_CASE' ? doc.relations : doc.messages
    const seen = new Set<string>()
    for (const item of [...nodes, ...edges]) {
      if (seen.has(item.id)) ctx.addIssue({ code: 'custom', message: '图内编号不能重复', path: ['id'] })
      seen.add(item.id)
    }
    const nodeIds = new Set(nodes.map(n => n.id))
    const actorIds = new Set(doc.kind === 'USE_CASE' ? doc.actors.map(n => n.id) : [])
    const caseIds = new Set(doc.kind === 'USE_CASE' ? doc.useCases.map(n => n.id) : [])
    edges.forEach((edge, index) => {
      const path = [doc.kind === 'USE_CASE' ? 'relations' : 'messages', index]
      if (!nodeIds.has(edge.fromId) || !nodeIds.has(edge.toId)) {
        ctx.addIssue({ code: 'custom', message: '关系或消息端点不存在', path })
      }
      if (doc.kind === 'USE_CASE') {
        const relation = edge as UseCaseRelation
        // ASSOCIATION is stored actor -> use case; include/extend point use case -> use case.
        const valid = relation.type === 'ASSOCIATION'
          ? actorIds.has(edge.fromId) && caseIds.has(edge.toId)
          : caseIds.has(edge.fromId) && caseIds.has(edge.toId) && edge.fromId !== edge.toId
        if (!valid) ctx.addIssue({ code: 'custom', message: '关系类型与端点不匹配', path })
      }
    })
    if (doc.kind === 'SEQUENCE') {
      let previous = 0
      doc.messages.forEach((message, index) => {
        if (message.seq <= previous) ctx.addIssue({
          code: 'custom', message: '消息序号必须严格递增', path: ['messages', index, 'seq'],
        })
        previous = message.seq
      })
    }
  })

export function emptyUmlDocument(kind: UmlDocument['kind']): UmlDocument {
  return kind === 'USE_CASE'
    ? { formatVersion: 1, kind, actors: [], useCases: [], relations: [] }
    : { formatVersion: 1, kind, lifelines: [], messages: [] }
}

/** Removing editor-local nodes also removes their edges; not business-object unlinking. */
export function removeUmlNode(doc: UmlDocument, nodeId: string): UmlDocument {
  if (doc.kind === 'USE_CASE') return {
    ...doc,
    actors: doc.actors.filter(n => n.id !== nodeId),
    useCases: doc.useCases.filter(n => n.id !== nodeId),
    relations: doc.relations.filter(r => r.fromId !== nodeId && r.toId !== nodeId),
  }
  return {
    ...doc,
    lifelines: doc.lifelines.filter(n => n.id !== nodeId),
    messages: doc.messages.filter(m => m.fromId !== nodeId && m.toId !== nodeId)
      .map((m, index) => ({ ...m, seq: index + 1 })),
  }
}

/** UI up/down control; immutable, and seq follows the new visual order. */
export function moveSequenceMessage(doc: SequenceDocument, messageId: string, offset: -1 | 1): SequenceDocument {
  const index = doc.messages.findIndex(m => m.id === messageId)
  const destination = index + offset
  if (index < 0 || destination < 0 || destination >= doc.messages.length) return doc
  const messages = [...doc.messages]
  const current = messages[index]!
  messages[index] = messages[destination]!
  messages[destination] = current
  return { ...doc, messages: messages.map((m, i) => ({ ...m, seq: i + 1 })) }
}

import { useId } from 'react'
import type { UmlDocument, UseCaseDocument, SequenceDocument } from '../../../../src/modules/uml/document'

/** Render only SVG elements owned by React. User text never becomes markup/URLs. */
export default function UmlPreview({ document }: { document: UmlDocument }) {
  const markerId = `uml-arrow-${useId().replace(/[^a-zA-Z0-9]/g, '')}`
  return (
    <div className="uml-preview" tabIndex={0} aria-label="图预览滚动区域">
      {document.kind === 'USE_CASE'
        ? <UseCasePreview document={document} markerId={markerId} />
        : <SequencePreview document={document} markerId={markerId} />}
    </div>
  )
}

function ArrowDefs({ id }: { id: string }) {
  return <defs>
    <marker id={`${id}-open`} markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto" markerUnits="userSpaceOnUse">
      <path d="M1 1 L9 5 L1 9" fill="none" stroke="currentColor" strokeWidth="1.5" />
    </marker>
    <marker id={`${id}-filled`} markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto" markerUnits="userSpaceOnUse">
      <path d="M1 1 L9 5 L1 9 Z" fill="currentColor" />
    </marker>
  </defs>
}

const short = (text: string, max = 20) => {
  const chars = Array.from(text)
  return chars.length > max ? `${chars.slice(0, max - 1).join('')}…` : text
}

function UseCasePreview({ document: doc, markerId }: { document: UseCaseDocument; markerId: string }) {
  const height = Math.max(260, Math.max(doc.actors.length, doc.useCases.length) * 115 + 90)
  const actors = new Map(doc.actors.map((n, i) => [n.id, { ...n, y: 85 + i * 115 }]))
  const cases = new Map(doc.useCases.map((n, i) => [n.id, { ...n, y: 85 + i * 115 }]))
  return <svg role="img" aria-label="用例图预览" viewBox={`0 0 760 ${height}`} width="760" height={height}>
    <title>用例图：{doc.actors.length} 个参与者，{doc.useCases.length} 个用例</title>
    <ArrowDefs id={markerId} />
    <rect x="285" y="20" width="450" height={height - 40} rx="8" className="uml-boundary" />
    {doc.relations.map(relation => {
      const from = relation.type === 'ASSOCIATION' ? actors.get(relation.fromId) : cases.get(relation.fromId)
      const to = cases.get(relation.toId)
      if (!from || !to) return null
      if (relation.type === 'ASSOCIATION') return <line key={relation.id} x1="165" y1={from.y} x2="335" y2={to.y} className="uml-edge" />
      const middle = (from.y + to.y) / 2
      return <g key={relation.id}>
        <path d={`M575 ${from.y} C700 ${from.y} 700 ${to.y} 575 ${to.y}`} className="uml-edge uml-dashed" markerEnd={`url(#${markerId}-open)`} />
        <text x="665" y={middle} textAnchor="middle" className="uml-edge-label">«{relation.type.toLowerCase()}»</text>
      </g>
    })}
    {[...actors.values()].map(actor => <g key={actor.id}>
      <title>{actor.name}</title>
      <circle cx="130" cy={actor.y - 25} r="12" className="uml-actor" />
      <path d={`M130 ${actor.y - 13} v35 M105 ${actor.y} h50 M130 ${actor.y + 22} l-20 25 M130 ${actor.y + 22} l20 25`} className="uml-edge" />
      <text x="130" y={actor.y + 67} textAnchor="middle">{short(actor.name, 16)}</text>
    </g>)}
    {[...cases.values()].map(useCase => <g key={useCase.id}>
      <title>{useCase.name}</title>
      <ellipse cx="455" cy={useCase.y} rx="120" ry="35" className="uml-node" />
      <text x="455" y={useCase.y + 5} textAnchor="middle">{short(useCase.name, 16)}</text>
    </g>)}
    {!doc.actors.length && !doc.useCases.length && <text x="380" y="130" textAnchor="middle">添加参与者和用例后在此预览</text>}
  </svg>
}

function SequencePreview({ document: doc, markerId }: { document: SequenceDocument; markerId: string }) {
  const width = Math.max(760, doc.lifelines.length * 230 + 160)
  const height = Math.max(280, doc.messages.length * 85 + 150)
  const lines = new Map(doc.lifelines.map((line, i) => [line.id, { ...line, x: 100 + i * 230 }]))
  return <svg role="img" aria-label="时序图预览" viewBox={`0 0 ${width} ${height}`} width={width} height={height}>
    <title>时序图：{doc.lifelines.length} 条生命线，{doc.messages.length} 条消息</title>
    <ArrowDefs id={markerId} />
    {[...lines.values()].map(line => <g key={line.id}>
      <title>{line.name}</title>
      <rect x={line.x - 90} y="20" width="180" height="45" rx="5" className="uml-node" />
      <text x={line.x} y="48" textAnchor="middle">{short(line.name, 12)}</text>
      <line x1={line.x} y1="65" x2={line.x} y2={height - 20} className="uml-lifeline" />
    </g>)}
    {doc.messages.map((message, i) => {
      const from = lines.get(message.fromId)
      const to = lines.get(message.toId)
      if (!from || !to) return null
      const y = 115 + i * 85
      const self = from.x === to.x
      const dash = message.kind === 'return' ? 'uml-dashed' : ''
      const marker = `url(#${markerId}-${message.kind === 'sync' ? 'filled' : 'open'})`
      return <g key={message.id}>
        <title>{message.seq}. {message.label} ({message.kind})</title>
        {self
          ? <path d={`M${from.x} ${y} h75 v30 h-75`} className={`uml-edge ${dash}`} markerEnd={marker} />
          : <line x1={from.x} y1={y} x2={to.x} y2={y} className={`uml-edge ${dash}`} markerEnd={marker} />}
        <text x={self ? from.x + 10 : (from.x + to.x) / 2} y={y - 12} textAnchor={self ? 'start' : 'middle'} className="uml-edge-label">
          {message.seq}. {short(message.label, 22)} [{message.kind}]
        </text>
      </g>
    })}
    {!doc.lifelines.length && <text x="380" y="140" textAnchor="middle">添加生命线和消息后在此预览</text>}
  </svg>
}

import { useMemo } from 'react'
import {
  moveSequenceMessage, removeUmlNode, umlDocumentSchema, UML_EDITOR_LIMITS,
  useCaseRelationTypes, sequenceMessageTypes,
} from '../../../../src/modules/uml/document'
import type {
  UmlDocument, UseCaseDocument, SequenceDocument, UseCaseRelation, SequenceMessage,
} from '../../../../src/modules/uml/document'
import UmlPreview from './UmlPreview'
import './uml.css'

type Props = {
  document: UmlDocument
  onChange: (document: UmlDocument) => void
  /** Presentation only, never a replacement for server-side can()/visibilityScope(). */
  readOnly?: boolean
}
const newId = () => crypto.randomUUID()

/** Controlled editor, no API calls, project data, persistent cache or fake save action. */
export default function UmlEditor({ document: doc, onChange, readOnly = false }: Props) {
  const validation = useMemo(() => umlDocumentSchema.safeParse(doc), [doc])
  const update = (next: UmlDocument) => { if (!readOnly) onChange(next) }
  return <section className="uml-editor" aria-label={doc.kind === 'USE_CASE' ? '用例图编辑器' : '时序图编辑器'}>
    <p className="uml-notice">{readOnly ? '只读预览：不可修改图稿。' : '图稿仅在当前编辑器内修改；项目保存与关联接口尚未接入。'}</p>
    <div className="uml-workspace">
      <div className="uml-controls">
        <fieldset disabled={readOnly} className="uml-fieldset">
          <legend>{doc.kind === 'USE_CASE' ? '用例图结构' : '时序图结构'}</legend>
          {doc.kind === 'USE_CASE'
            ? <UseCaseControls document={doc} onChange={update} />
            : <SequenceControls document={doc} onChange={update} />}
        </fieldset>
        {!validation.success && <div role="alert" className="uml-errors">
          <strong>图稿尚未通过校验</strong>
          <ul>{validation.error.issues.map((issue, i) => <li key={i}>{issue.path.join('.') || 'document'}：{issue.message}</li>)}</ul>
        </div>}
      </div>
      <UmlPreview document={doc} />
    </div>
  </section>
}

function NodeRows({ nodes, label, onName, onRemove }: {
  nodes: { id: string; name: string }[]; label: string
  onName: (id: string, name: string) => void; onRemove: (id: string) => void
}) {
  return <div className="uml-node-rows">{nodes.map((node, index) => <div className="uml-node-row" key={node.id}>
    <label>{label} {index + 1}
      <input value={node.name} maxLength={UML_EDITOR_LIMITS.text} onChange={event => onName(node.id, event.target.value)} />
    </label>
    <button type="button" aria-label={`删除${label} ${index + 1}`} onClick={() => onRemove(node.id)}>删除</button>
  </div>)}</div>
}

function Endpoint({ label, value, options, onChange }: {
  label: string; value: string; options: { id: string; name: string }[]; onChange: (id: string) => void
}) {
  return <label>{label}<select value={value} onChange={event => onChange(event.target.value)}>
    <option value="" disabled>请选择</option>
    {options.map(node => <option key={node.id} value={node.id}>{node.name || '（未命名）'}</option>)}
  </select></label>
}

function UseCaseControls({ document: doc, onChange }: { document: UseCaseDocument; onChange: (doc: UmlDocument) => void }) {
  const updateNode = (group: 'actors' | 'useCases', id: string, name: string) => onChange({
    ...doc, [group]: doc[group].map(node => node.id === id ? { ...node, name } : node),
  })
  const patchRelation = (id: string, patch: Partial<UseCaseRelation>) => onChange({
    ...doc, relations: doc.relations.map(relation => relation.id === id ? { ...relation, ...patch } : relation),
  })
  function addRelation() {
    if (!doc.actors[0] || !doc.useCases[0]) return
    onChange({ ...doc, relations: [...doc.relations, {
      id: newId(), type: 'ASSOCIATION', fromId: doc.actors[0].id, toId: doc.useCases[0].id,
    }] })
  }
  return <>
    <h3>参与者</h3>
    <NodeRows nodes={doc.actors} label="参与者" onName={(id, name) => updateNode('actors', id, name)} onRemove={id => onChange(removeUmlNode(doc, id))} />
    <button type="button" disabled={doc.actors.length >= UML_EDITOR_LIMITS.nodes} onClick={() => onChange({ ...doc, actors: [...doc.actors, { id: newId(), name: '新参与者' }] })}>添加参与者</button>
    <h3>用例</h3>
    <NodeRows nodes={doc.useCases} label="用例" onName={(id, name) => updateNode('useCases', id, name)} onRemove={id => onChange(removeUmlNode(doc, id))} />
    <button type="button" disabled={doc.useCases.length >= UML_EDITOR_LIMITS.nodes} onClick={() => onChange({ ...doc, useCases: [...doc.useCases, { id: newId(), name: '新用例' }] })}>添加用例</button>
    <h3>关系</h3>
    {doc.relations.map((relation, index) => <div className="uml-relation" key={relation.id}>
      <label>关系 {index + 1} 类型<select value={relation.type} onChange={event => {
        const type = event.target.value as UseCaseRelation['type']
        const fromId = type === 'ASSOCIATION' ? doc.actors[0]?.id ?? '' : doc.useCases[0]?.id ?? ''
        const toId = type === 'ASSOCIATION' ? doc.useCases[0]?.id ?? '' : doc.useCases[1]?.id ?? ''
        patchRelation(relation.id, { type, fromId, toId })
      }}>{useCaseRelationTypes.map(type => <option key={type}>{type}</option>)}</select></label>
      <Endpoint label={`关系 ${index + 1} 起点`} value={relation.fromId} options={relation.type === 'ASSOCIATION' ? doc.actors : doc.useCases} onChange={fromId => patchRelation(relation.id, { fromId })} />
      <Endpoint label={`关系 ${index + 1} 终点`} value={relation.toId} options={doc.useCases} onChange={toId => patchRelation(relation.id, { toId })} />
      <button type="button" aria-label={`删除关系 ${index + 1}`} onClick={() => onChange({ ...doc, relations: doc.relations.filter(r => r.id !== relation.id) })}>删除关系</button>
    </div>)}
    <button type="button" disabled={(!doc.actors.length && doc.useCases.length < 2) || !doc.useCases.length || doc.relations.length >= UML_EDITOR_LIMITS.edges} onClick={() => {
      // Two use cases can be related without an actor.
      if (!doc.actors.length && doc.useCases[0] && doc.useCases[1]) {
        onChange({ ...doc, relations: [...doc.relations, { id: newId(), type: 'INCLUDE', fromId: doc.useCases[0].id, toId: doc.useCases[1].id }] })
      } else addRelation()
    }}>添加关系</button>
    <p className="uml-help">ASSOCIATION：参与者 → 用例；INCLUDE / EXTEND：用例 → 另一用例。</p>
  </>
}

function SequenceControls({ document: doc, onChange }: { document: SequenceDocument; onChange: (doc: UmlDocument) => void }) {
  const patch = (id: string, change: Partial<SequenceMessage>) => onChange({
    ...doc, messages: doc.messages.map(message => message.id === id ? { ...message, ...change } : message),
  })
  return <>
    <h3>生命线</h3>
    <NodeRows nodes={doc.lifelines} label="生命线" onName={(id, name) => onChange({ ...doc, lifelines: doc.lifelines.map(line => line.id === id ? { ...line, name } : line) })} onRemove={id => onChange(removeUmlNode(doc, id))} />
    <button type="button" disabled={doc.lifelines.length >= UML_EDITOR_LIMITS.nodes} onClick={() => onChange({ ...doc, lifelines: [...doc.lifelines, { id: newId(), name: '新生命线' }] })}>添加生命线</button>
    <h3>有序消息</h3>
    {doc.messages.map((message, index) => <div className="uml-relation" key={message.id}>
      <label>消息 {index + 1} 内容<input value={message.label} maxLength={UML_EDITOR_LIMITS.text} onChange={event => patch(message.id, { label: event.target.value })} /></label>
      <label>消息 {index + 1} 类型<select value={message.kind} onChange={event => patch(message.id, { kind: event.target.value as SequenceMessage['kind'] })}>
        {sequenceMessageTypes.map(type => <option key={type}>{type}</option>)}
      </select></label>
      <Endpoint label={`消息 ${index + 1} 发送方`} value={message.fromId} options={doc.lifelines} onChange={fromId => patch(message.id, { fromId })} />
      <Endpoint label={`消息 ${index + 1} 接收方`} value={message.toId} options={doc.lifelines} onChange={toId => patch(message.id, { toId })} />
      <div className="uml-actions">
        <button type="button" aria-label={`上移消息 ${index + 1}`} disabled={index === 0} onClick={() => onChange(moveSequenceMessage(doc, message.id, -1))}>上移</button>
        <button type="button" aria-label={`下移消息 ${index + 1}`} disabled={index === doc.messages.length - 1} onClick={() => onChange(moveSequenceMessage(doc, message.id, 1))}>下移</button>
        <button type="button" aria-label={`删除消息 ${index + 1}`} onClick={() => onChange({ ...doc, messages: doc.messages.filter(m => m.id !== message.id).map((m, i) => ({ ...m, seq: i + 1 })) })}>删除</button>
      </div>
    </div>)}
    <button type="button" disabled={!doc.lifelines.length || doc.messages.length >= UML_EDITOR_LIMITS.edges} onClick={() => {
      const from = doc.lifelines[0]
      if (!from) return
      onChange({ ...doc, messages: [...doc.messages, { id: newId(), fromId: from.id, toId: doc.lifelines[1]?.id ?? from.id, label: '新消息', kind: 'sync', seq: (doc.messages[doc.messages.length - 1]?.seq ?? 0) + 1 }] })
    }}>添加消息</button>
    <p className="uml-help">消息按当前顺序从上到下展示；上移/下移会同步调整递增序号。</p>
  </>
}

import { useState } from 'react'
import { createRoot } from 'react-dom/client'
import {
  emptyUmlDocument, umlDocumentSchema,
} from '../../../../src/modules/uml/document'
import type { UmlDocument } from '../../../../src/modules/uml/document'
import UmlEditor from './UmlEditor'

/** Isolated development fixture, not mounted in the platform route registry.
 * No API mock and no project data: actual editor code runs against local memory.
 */
function EditorPreview() {
  const [kind, setKind] = useState<UmlDocument['kind']>('USE_CASE')
  const [documents, setDocuments] = useState<Record<UmlDocument['kind'], UmlDocument>>({
    USE_CASE: emptyUmlDocument('USE_CASE'), SEQUENCE: emptyUmlDocument('SEQUENCE'),
  })
  const [readOnly, setReadOnly] = useState(false)
  const [input, setInput] = useState('')
  const [error, setError] = useState('')
  const document = documents[kind]
  const update = (next: UmlDocument) => {
    if (readOnly) return
    setDocuments(previous => ({ ...previous, [next.kind]: next }))
  }
  const json = JSON.stringify(document, null, 2)
  function load() {
    if (readOnly) return
    try {
      if (input.length > 1_000_000) throw new Error('本地导入内容过大')
      const parsed = umlDocumentSchema.safeParse(JSON.parse(input))
      if (!parsed.success) {
        setError(parsed.error.issues.map(issue => `${issue.path.join('.')}：${issue.message}`).join('；'))
        return
      }
      update(parsed.data)
      setKind(parsed.data.kind)
      setError('')
    } catch {
      setError('图稿 JSON 无法解析或超过本地导入安全上限；原图稿未改变。')
    }
  }
  function download() {
    const parsed = umlDocumentSchema.safeParse(document)
    if (!parsed.success) { setError('图稿校验失败，请先修正编辑内容。'); return }
    setError('')
    const url = URL.createObjectURL(new Blob([JSON.stringify(parsed.data, null, 2)], { type: 'application/json' }))
    const anchor = window.document.createElement('a')
    anchor.href = url
    anchor.download = `uml-${kind.toLowerCase()}.json`
    anchor.click()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
  return <main className="uml-dev-page">
    <h1>在线 UML 编辑器 · 独立开发验证</h1>
    <p className="uml-notice">不是正式项目页面。没有数据库保存、对象关联或服务端鉴权；刷新会清空内存图稿。下载/载入 JSON 仅验证图稿往返，不代表项目持久化验收。</p>
    <div className="uml-actions">
      <button type="button" aria-pressed={kind === 'USE_CASE'} onClick={() => setKind('USE_CASE')}>编辑用例图</button>
      <button type="button" aria-pressed={kind === 'SEQUENCE'} onClick={() => setKind('SEQUENCE')}>编辑时序图</button>
      <label><input type="checkbox" checked={readOnly} onChange={event => setReadOnly(event.target.checked)} />只读交互检查（非权限验证）</label>
    </div>
    <UmlEditor document={document} onChange={update} readOnly={readOnly} />
    <section className="uml-transfer">
      <h2>本地图稿往返验证</h2>
      <button type="button" onClick={download}>下载本地图稿 JSON</button>
      <details><summary>当前图稿 JSON</summary><pre data-testid="document-json">{json}</pre></details>
      <label>待载入图稿 JSON<textarea value={input} maxLength={1_000_000} disabled={readOnly} onChange={event => setInput(event.target.value)} rows={6} /></label>
      <button type="button" disabled={readOnly} onClick={load}>载入图稿 JSON</button>
      {error && <p role="alert" className="uml-errors">{error}</p>}
    </section>
  </main>
}

const root = document.getElementById('root')
if (root) createRoot(root).render(<EditorPreview />)

