// 为什么需要这 7 张表：AC1 要求「在线创建并编辑用例图与时序图（非仅上传）」，
// AC2 要求「图可关联项目 / 业务目标 / 用户活动 / 用户故事 / 任务」。既有表没有任何字段
// 能承载图、节点、边或类型化关联，故本票新增。依据：`docs/role-b-uml-design.md` §3（FROZEN v1.0）。
//
// 三处关键取舍（设计 §3.1）：
//   ① 不落任何几何坐标：只落结构 + 序（`UmlNode.orderIndex` 生命线序、`UmlEdge.seq` 消息序）。
//      已批准口径明确「不做自动布局 / 自由画布语义校验」，落坐标会把画布语义带回来。
//   ② 4 张真实关联表（Goal / Activity / Story / Task）各两个真实外键、两端 Cascade：
//      多态列（如 `ObjectVisibility`）无外键 ⇒ 无 DB 级联 ⇒ 删任务后留孤儿关联行，与
//      已批准口径「关联行 Cascade」冲突；且若对任务引用用 Restrict，会让**既有
//      `DELETE /tasks/:taskId`（端点 29）开始失败**。
//   ③ 两类图共用 3 张表（`UmlDiagram` / `UmlNode` / `UmlEdge`），用 `kind` + `nodeType` /
//      `edgeType` 判别；枚举合法性由写入层（Zod）保证，与文件头第 1 条一致（DB 不约束枚举）。
//
// 删除语义理由（设计 §3.6）：
//   UmlDiagram.projectId   → Restrict：项目不应被删掉而留下孤儿图。
//   UmlDiagram.ownerUserId → Restrict：人不该被删掉而留下无主图。
//   UmlNode / UmlEdge → UmlDiagram → Cascade：图内容的从属物。
//   UmlEdge 两端 → UmlNode（复合外键）→ Cascade：节点删除后残留边即脏数据。
//   4 张关联表两端 → Cascade：关联行只是连接，任一端消失即失去意义；删任务 / 故事时
//     关联行自动消失，旧删除端点零改动。
//
// 边同图约束由数据库兜底（设计 §3.3 / §3.7 实测）：`UmlEdge` 用**复合外键**
//   `(diagramId, sourceNodeId)` / `(diagramId, targetNodeId) → UmlNode(diagramId, id)`，
//   因此「A 图的边指向 B 图的节点」在物理上不可能落库（跨图建边得 P2003），
//   不依赖写入层是否漏检。为此 `UmlNode` 必须有 `@@unique([diagramId, id])` 作为引用目标。
model UmlDiagram {
  id          String   @id @default(uuid())
  projectId   String
  kind        String // 'USECASE' | 'SEQUENCE'；创建后不可变（写入层保证）
  title       String
  description String?
  ownerUserId String // 创建时取当前 PM；可转移给任意项目成员（写入层校验）
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  project Project @relation(fields: [projectId], references: [id], onDelete: Restrict)
  owner   User    @relation("UmlDiagramOwner", fields: [ownerUserId], references: [id], onDelete: Restrict)

  nodes      UmlNode[]
  edges      UmlEdge[]
  goals      UmlDiagramGoal[]
  activities UmlDiagramActivity[]
  stories    UmlDiagramStory[]
  tasks      UmlDiagramTask[]

  // 列表主查询（按项目 + 类型）；负责人维度的「我的图」
  @@index([projectId, kind])
  @@index([ownerUserId])
}

model UmlNode {
  id         String   @id @default(uuid())
  diagramId  String
  nodeType   String // 用例图：'ACTOR' | 'USECASE'；时序图：'LIFELINE'
  name       String
  orderIndex Int      @default(0) // 序，不是坐标：时序图生命线横向排列序；用例图恒 0
  createdAt  DateTime @default(now())

  diagram UmlDiagram @relation(fields: [diagramId], references: [id], onDelete: Cascade)
  // 复合外键的目标（UmlEdge 用 (diagramId, id) 引用），故必须唯一
  outgoingEdges UmlEdge[] @relation("UmlEdgeSource")
  incomingEdges UmlEdge[] @relation("UmlEdgeTarget")

  @@unique([diagramId, id])
  @@index([diagramId])
}

model UmlEdge {
  id           String   @id @default(uuid())
  diagramId    String
  edgeType     String // 用例图：'ASSOCIATION' | 'INCLUDE' | 'EXTEND'；时序图：'SYNC' | 'ASYNC' | 'RETURN'
  sourceNodeId String
  targetNodeId String
  label        String?
  seq          Int? // 仅时序图（消息序号，服务端分配）；用例图恒 null
  createdAt    DateTime @default(now())

  diagram UmlDiagram @relation(fields: [diagramId], references: [id], onDelete: Cascade)
  // 复合外键把 diagramId 一起带进引用目标 ⇒ 边两端必然属于同一张图（DB 兜底，见上方说明）
  source UmlNode @relation("UmlEdgeSource", fields: [diagramId, sourceNodeId], references: [diagramId, id], onDelete: Cascade)
  target UmlNode @relation("UmlEdgeTarget", fields: [diagramId, targetNodeId], references: [diagramId, id], onDelete: Cascade)

  // 时序图内 seq 唯一（注意：是「唯一」不是「严格递增」，递增语义只能由写入层保证）；
  // SQLite 唯一索引允许多个 NULL ⇒ 用例图多条 seq = null 的边可共存（设计 §3.3 / §3.7 实测）
  @@unique([diagramId, seq])
  @@index([diagramId])
  @@index([sourceNodeId])
  @@index([targetNodeId])
}

// 图 ↔ 业务目标（目标 / 活动无敏感维度，恒对项目成员可见；见设计 §Z）
model UmlDiagramGoal {
  diagramId String
  goalId    String

  diagram UmlDiagram   @relation(fields: [diagramId], references: [id], onDelete: Cascade)
  goal    BusinessGoal @relation(fields: [goalId], references: [id], onDelete: Cascade)

  @@id([diagramId, goalId])
  @@index([goalId])
}

// 图 ↔ 用户活动
model UmlDiagramActivity {
  diagramId  String
  activityId String

  diagram  UmlDiagram   @relation(fields: [diagramId], references: [id], onDelete: Cascade)
  activity UserActivity @relation(fields: [activityId], references: [id], onDelete: Cascade)

  @@id([diagramId, activityId])
  @@index([activityId])
}

// 图 ↔ 用户故事（可见性交集口径的输入之一）
model UmlDiagramStory {
  diagramId String
  storyId   String

  diagram UmlDiagram @relation(fields: [diagramId], references: [id], onDelete: Cascade)
  story   UserStory  @relation(fields: [storyId], references: [id], onDelete: Cascade)

  @@id([diagramId, storyId])
  @@index([storyId])
}

// 图 ↔ 任务（可见性交集口径的另一输入；**两端 Cascade** 是保住端点 29 删除语义的关键）
model UmlDiagramTask {
  diagramId String
  taskId    String

  diagram UmlDiagram @relation(fields: [diagramId], references: [id], onDelete: Cascade)
  task    Task       @relation(fields: [taskId], references: [id], onDelete: Cascade)

  @@id([diagramId, taskId])
  @@index([taskId])
}

/**
 * US-06 甘特图（GitHub #26，本地 #11 只读 + #12 写路径）—— 路由插件。
 *
 * 只导出插件，**不自行挂载生产路由**：正式注册行在冻结的 `src/routes.ts` 里
 * （契约决策 I-0 / I-9）；公共挂载由主代理另批完成。
 *
 * 端点（仓库既有契约**无 `/api` 前缀**，与其它模块一致）：
 *
 *   - `GET /projects/:projectId/gantt`               200 `GanttView`
 *       权限 `project.read`；非成员 / 项目不存在 → 404（响应逐字一致，不泄漏存在性）。
 *   - `POST /projects/:projectId/milestones`         201 `MilestoneWriteView`
 *   - `PATCH /milestones/:milestoneId`               200 `MilestoneWriteView`
 *   - `DELETE /milestones/:milestoneId`              204
 *   - `POST /projects/:projectId/task-dependencies`  201 `TaskDependencyView`
 *   - `DELETE /task-dependencies/:dependencyId`      204
 *
 * 写端点权限一律 `gantt.write`（仅 PM：MEMBER / VIEWER 403，非成员 404，未登录 401）；
 * **判权在 `./write.ts` 内通过唯一入口 `can()` 完成** —— 按 id 操作必须先解析真实
 * `projectId` 再判权，本层只做形状校验（Zod）与响应码。
 *
 * 错误处理沿用仓库既有约定（`AppError` + `requireAuth`，不自造信封、不改错误信封形状）。
 */
import type { FastifyInstance } from 'fastify'
import { z } from 'zod'
import { currentUserId, requireAuth } from '../../auth/actor.js'
import { AppError } from '../../shared/errors.js'
import { dateSchema, toFieldErrors } from '../../shared/validation.js'
import { createAuthorization } from '../authz/permissions.js'
import type { RouteContext } from '../../routes.js'
import { buildGanttView } from './service.js'
import { MILESTONE_NAME_MAX_LENGTH } from './types.js'
import {
  createDependency,
  createMilestone,
  deleteDependency,
  deleteMilestone,
  updateMilestone,
} from './write.js'

/**
 * 「项目不存在 / 我不可见」的**单一 404 文案**（契约决策 I-3）。
 * 与 `src/modules/project/plugin.ts`、`src/modules/workload/plugin.ts` 取值逐字一致。
 */
const PROJECT_NOT_FOUND_MESSAGE = '项目不存在'

/**
 * 新建 / 修改里程碑。
 *
 * `dueDate` 只校验 `'YYYY-MM-DD'` 形状（决策 I-10）；`2026-02-30` 这类日历不存在
 * 的值由 `./write.ts` 判 422 `INVALID_VALUE`（业务校验不塞进 Zod）。
 * `taskIds` 在 PATCH 里**出现即整体替换**关联集。
 */
const milestoneCreateSchema = z.object({
  name: z.string().trim().min(1).max(MILESTONE_NAME_MAX_LENGTH),
  dueDate: dateSchema,
  ownerUserId: z.string().min(1).nullable().optional(),
  taskIds: z.array(z.string().min(1)).optional(),
})

/** 修改里程碑：全部字段可选（部分更新）。 */
const milestonePatchSchema = milestoneCreateSchema.partial()

/**
 * 新建 FS 依赖。
 *
 * `type` 刻意**不用** `z.enum(['FS'])` 单独表达「非 FS」：非 `'FS'` 取值由 `./write.ts`
 * 判 422 `INVALID_VALUE`（field `type`，原因在 message），此处只校验形状（非空字符串）。
 */
const dependencyCreateSchema = z.object({
  predecessorTaskId: z.string().min(1),
  successorTaskId: z.string().min(1),
  type: z.string().min(1).optional(),
})

function validationFailed(error: z.ZodError): AppError {
  return new AppError(422, 'VALIDATION_FAILED', '字段校验失败', toFieldErrors(error.issues))
}

export function registerGanttRoutes(app: FastifyInstance, ctx: RouteContext): void {
  // 唯一鉴权入口来自 authz（决策 I-9：不复制权限逻辑，一律问 can()）。
  const { can } = createAuthorization(ctx.prisma)

  // ===========================================================================
  // GET /projects/:projectId/gantt —— 权限 project.read
  //
  // 响应  200 GanttView
  // 错误  401 UNAUTHENTICATED；404 NOT_FOUND（非成员 / 项目不存在）
  // ===========================================================================
  app.get('/projects/:projectId/gantt', { preHandler: requireAuth }, async (req, reply) => {
    const actorUserId = currentUserId(req)
    const { projectId } = req.params as { projectId: string }

    // 契约 I-5 约束 2：status / code 由 can() 直接给出，调用方不自行判断 403/404。
    const decision = await can(actorUserId, 'project.read', { kind: 'project', projectId })
    if (!decision.allow) {
      throw new AppError(decision.status, decision.code, PROJECT_NOT_FOUND_MESSAGE)
    }

    const view = await buildGanttView(ctx.prisma, actorUserId, projectId)
    return reply.status(200).send(view)
  })

  // ===========================================================================
  // POST /projects/:projectId/milestones —— 权限 gantt.write（仅 PM）
  //
  // 请求  { name, dueDate, ownerUserId?, taskIds? }
  // 响应  201 MilestoneWriteView
  // 错误  401 UNAUTHENTICATED；403 FORBIDDEN；404 NOT_FOUND；
  //       422 VALIDATION_FAILED（name；dueDate: INVALID_FORMAT | INVALID_VALUE；
  //           ownerUserId: NOT_PROJECT_MEMBER；taskIds: CROSS_PROJECT_REF）
  // ===========================================================================
  app.post('/projects/:projectId/milestones', { preHandler: requireAuth }, async (req, reply) => {
    const actorUserId = currentUserId(req)
    const { projectId } = req.params as { projectId: string }

    const parsed = milestoneCreateSchema.safeParse(req.body)
    if (!parsed.success) throw validationFailed(parsed.error)

    const milestone = await createMilestone(ctx.prisma, actorUserId, projectId, parsed.data)
    return reply.status(201).send(milestone)
  })

  // ===========================================================================
  // PATCH /milestones/:milestoneId —— 权限 gantt.write（仅 PM）
  //
  // 响应  200 MilestoneWriteView（`taskIds` 出现即整体替换关联集）
  // 错误  401；403 FORBIDDEN；404 NOT_FOUND（里程碑不存在 / 非成员，文案一致）；
  //       422 VALIDATION_FAILED（同上）
  // ===========================================================================
  app.patch('/milestones/:milestoneId', { preHandler: requireAuth }, async (req, reply) => {
    const actorUserId = currentUserId(req)
    const { milestoneId } = req.params as { milestoneId: string }

    const parsed = milestonePatchSchema.safeParse(req.body)
    if (!parsed.success) throw validationFailed(parsed.error)

    const milestone = await updateMilestone(ctx.prisma, actorUserId, milestoneId, parsed.data)
    return reply.status(200).send(milestone)
  })

  // ===========================================================================
  // DELETE /milestones/:milestoneId —— 权限 gantt.write（仅 PM）
  //
  // 响应  204（无响应体；`TaskMilestone` 关联行由 schema 级联清理）
  // 错误  401；403 FORBIDDEN；404 NOT_FOUND
  // ===========================================================================
  app.delete('/milestones/:milestoneId', { preHandler: requireAuth }, async (req, reply) => {
    const actorUserId = currentUserId(req)
    const { milestoneId } = req.params as { milestoneId: string }

    await deleteMilestone(ctx.prisma, actorUserId, milestoneId)
    return reply.status(204).send()
  })

  // ===========================================================================
  // POST /projects/:projectId/task-dependencies —— 权限 gantt.write（仅 PM）
  //
  // 请求  { predecessorTaskId, successorTaskId, type? }（type 缺省 FS）
  // 响应  201 TaskDependencyView
  // 错误  401；403 FORBIDDEN；404 NOT_FOUND；
  //       422 VALIDATION_FAILED（type: INVALID_VALUE（仅支持 FS）；
  //           successorTaskId: INVALID_VALUE（自依赖）；
  //           predecessorTaskId / successorTaskId: CROSS_PROJECT_REF）；
  //       409 CONFLICT（successorTaskId: DUPLICATE（重复边）或 INVALID_VALUE（FS 环））
  //       —— 字段码全部取决策 I-4 冻结表内取值，原因由 message 说明。
  // ===========================================================================
  app.post(
    '/projects/:projectId/task-dependencies',
    { preHandler: requireAuth },
    async (req, reply) => {
      const actorUserId = currentUserId(req)
      const { projectId } = req.params as { projectId: string }

      const parsed = dependencyCreateSchema.safeParse(req.body)
      if (!parsed.success) throw validationFailed(parsed.error)

      const dependency = await createDependency(ctx.prisma, actorUserId, projectId, parsed.data)
      return reply.status(201).send(dependency)
    },
  )

  // ===========================================================================
  // DELETE /task-dependencies/:dependencyId —— 权限 gantt.write（仅 PM）
  //
  // 响应  204（无响应体）
  // 错误  401；403 FORBIDDEN；404 NOT_FOUND
  // ===========================================================================
  app.delete(
    '/task-dependencies/:dependencyId',
    { preHandler: requireAuth },
    async (req, reply) => {
      const actorUserId = currentUserId(req)
      const { dependencyId } = req.params as { dependencyId: string }

      await deleteDependency(ctx.prisma, actorUserId, dependencyId)
      return reply.status(204).send()
    },
  )
}

/**
 * HTTP 层测试框架（T0 缺口修补：为契约要求的「接口层唯一 seam」提供基建）
 *
 * ===========================================================================
 * 为什么需要本文件
 * ===========================================================================
 *
 * 契约「Testing Decisions」规定：**HTTP 接口层是唯一测试 seam**，且
 * 「越权用例必须打接口，不能用『前端不渲染按钮』代替」。
 *
 * 但 T0 交付的 `buildApp()` 不接收数据库，而 `src/db/client.ts` 是绑定
 * `DATABASE_URL` 的模块级单例——因此**无法构造一个连临时库的 app**。
 * 结果：所有 HTTP 测试要么污染 dev.db，要么无法隔离。
 *
 * 本文件配合 `src/app.ts` 新增的 `prisma` 注入参数解决该问题：
 *   `buildApp({ prisma: tempDb.prisma })`
 *
 * 每个测试文件调用一次 `createHttpTestContext()`，得到：
 *   - 独立的临时 SQLite 库（已应用全部迁移，不与 dev.db 及其它测试文件互相污染）
 *   - 指向该库的 app 实例
 *   - `loginAs(userId)`：为任意用户签发令牌，**不依赖端点 1**
 *     （端点 1 `/auth/login` 属 M1 范围，尚未实现；本函数直接签发令牌，
 *      使接口测试在 M1 完成前即可编写）
 *   - `asUser(token)`：以该身份发请求
 *
 * 与 `src/db/test-support.ts` 的关系：复用其 `createTempDatabase()` /
 * `resetDatabase()`，不重复实现建库逻辑。
 * ===========================================================================
 */
import type { FastifyInstance } from 'fastify'
import request from 'supertest'
import { createRequire } from 'node:module'
import { buildApp } from '../src/app.js'
import { createTempDatabase, resetDatabase, type TestDatabase } from '../src/db/test-support.js'
import { hashToken } from '../src/auth/token.js'
import { hashPassword } from '../src/auth/password.js'

// `node:sqlite` 不在（本仓 Vite 6 的）node 内置模块名单里，静态 import 会被误解析为
// 裸模块 `sqlite`。用 createRequire 在运行时加载，绕开构建期解析。
const nodeRequire = createRequire(import.meta.url)
const { DatabaseSync } = nodeRequire('node:sqlite') as typeof import('node:sqlite')

export type HttpTestContext = {
  app: FastifyInstance
  db: TestDatabase['prisma']
  /** 清空全部表（按外键逆序），在 beforeEach 调用。 */
  reset: () => Promise<void>
  /** 为指定用户签发令牌（不经过 /auth/login，故不依赖 M1）。 */
  loginAs: (userId: string) => string
  /** 以某令牌身份发请求；传 null 表示不带 Authorization 头。 */
  asUser: (token: string | null) => {
    get: (url: string) => request.Test
    post: (url: string) => request.Test
    patch: (url: string) => request.Test
    put: (url: string) => request.Test
    delete: (url: string) => request.Test
  }
  /** 收尾：关闭 app、断开并删除临时库。 */
  dispose: () => Promise<void>
}

/** 测试用统一密码（明文）。工厂函数会用真实 scrypt 哈希写入。 */
export const TEST_PASSWORD = '[REDACTED_TEST_PASSWORD]'

export async function createHttpTestContext(): Promise<HttpTestContext> {
  const tempDb = createTempDatabase()

  // 关键：把临时库注入 app，使其不读 dev.db 单例
  const app = buildApp({ logger: false, prisma: tempDb.prisma })

  // 同步写会话表：契约 I-8 要求令牌「存库校验」，而 `loginAs` 必须保持同步签名
  // （200+ 调用点直接 `ctx.asUser(ctx.loginAs(x))`）。Prisma 无同步 API，故用
  // Node 内置 `node:sqlite` 的 DatabaseSync 直连同一临时库写入哈希。
  const sqlite = new DatabaseSync(tempDb.file)
  const setSession = sqlite.prepare(
    'UPDATE "User" SET "sessionTokenHash" = ?, "sessionTokenExpiresAt" = ? WHERE "id" = ?',
  )

  // 注意：此处**不调用** app.ready()。
  // Fastify 一旦 booted 就不允许再注册路由（会抛 "Root plugin has already booted"），
  // 而调用方通常需要在 ready 之前注册自己的探针端点。
  // 因此把 ready 的责任交给调用方：注册完探针后再 await app.ready()。
  // supertest 在每次请求时（而非构造时）读取地址，因此 ready 晚于本函数是安全的。

  const asUser = (token: string | null) => {
    const st = request(app.server)
    const withAuth = <T extends request.Test>(t: T): T => {
      if (token) t.set('Authorization', `Bearer ${token}`)
      return t
    }
    return {
      get: (url: string) => withAuth(st.get(url)),
      post: (url: string) => withAuth(st.post(url)),
      patch: (url: string) => withAuth(st.patch(url)),
      put: (url: string) => withAuth(st.put(url)),
      delete: (url: string) => withAuth(st.delete(url)),
    }
  }

  return {
    app,
    db: tempDb.prisma,
    reset: () => resetDatabase(tempDb.prisma),
    // 为指定用户签发**存库**的会话令牌（不经过 /auth/login，故不依赖 M1）。
    // 确定性令牌，使同一用户的多次 loginAs 不会互相作废。
    loginAs: (userId: string) => {
      const token = `test-token-${userId}`
      setSession.run(
        hashToken(token),
        new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        userId,
      )
      return token
    },
    asUser,
    dispose: async () => {
      sqlite.close()
      await app.close()
      await tempDb.dispose()
    },
  }
}

// ---------------------------------------------------------------------------
// 数据工厂（仅本骨架所需的最小集合）
//
// 契约「测试数据工厂」列出的 8 个函数属 T0.5 交付范围，由成员 2 / 成员 4 在
// 各自模块内使用时补齐。本文件只提供 HTTP 层测试自建数据所需的最小函数，
// **不覆盖、不替代** test/ 下可能出现的其它工厂定义。
// ---------------------------------------------------------------------------

/** 造一个用户（密码用真实 scrypt 哈希，便于将来接入端点 1 后可直接登录）。 */
export async function makeUser(
  db: HttpTestContext['db'],
  account: string,
  displayName = account,
): Promise<string> {
  const user = await db.user.create({
    data: { account, displayName, passwordHash: await hashPassword(TEST_PASSWORD) },
    select: { id: true },
  })
  return user.id
}

/** 造一个项目，并把 ownerUserId 设为该项目 PM（与端点 3 的副作用一致）。 */
export async function makeProject(
  db: HttpTestContext['db'],
  ownerUserId: string,
  name = '测试项目',
): Promise<string> {
  const project = await db.project.create({
    data: {
      name,
      ownerUserId,
      members: { create: { userId: ownerUserId, role: 'PM' } },
    },
    select: { id: true },
  })
  return project.id
}

/** 往项目里加成员并指定角色。 */
export async function makeMember(
  db: HttpTestContext['db'],
  projectId: string,
  userId: string,
  role: 'PM' | 'MEMBER' | 'VIEWER' = 'MEMBER',
): Promise<void> {
  await db.projectMember.create({ data: { projectId, userId, role } })
}

