/**
 * 前端 API 封装（US-01 前端壳）
 *
 * - 令牌存 localStorage，刷新后仍可保持登录（T0-04 验收：刷新保持登录）
 * - 统一带 Authorization: Bearer；失败时把契约的 ErrorResponse 转成 ApiError
 * - 类型从后端共享定义引入（只引类型，构建时被擦除，不打包后端代码）
 */
import type {
  Project,
  ProjectMemberView,
  ProjectRole,
  ProjectView,
  UserBrief,
} from '../../src/shared/types'

const TOKEN_KEY = 'aim.token'

export class ApiError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public details?: Array<{ field: string; code: string }>,
  ) {
    super(message)
    this.name = 'ApiError'
  }
}

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY)
}

export function setToken(token: string): void {
  localStorage.setItem(TOKEN_KEY, token)
}

export function clearToken(): void {
  localStorage.removeItem(TOKEN_KEY)
}

/**
 * 统一发请求并解析契约信封。
 *
 * 【US-03 / T3.11 的唯一一处改动】补 `export`。
 *
 * 原因：`docs/frontend-routes.md` 规定"其他模块只往 `web/src/pages/` 下新增页面"，
 * 但 US-03 的端点（10–22）也需要走同一个信封解析。若不导出本函数，US-03 只能在
 * 自己的页面目录里**再抄一遍** fetch + Authorization + ErrorResponse 解析 ——
 * 那正是契约「常见拼装失败与预防」表第一条（同一件事两份实现就会漂移）的成因。
 *
 * 因此这里只加一个关键字，**不改任何既有行为**；归属仍是 M2，请 M2 负责人复核。
 */
export async function apiFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers)
  if (init.body !== undefined && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json')
  }
  const token = getToken()
  if (token) headers.set('Authorization', `Bearer ${token}`)

  // 统一走 /api 前缀：SPA 的路由（/projects/:id/...）与后端契约路径（/projects）同名，
  // 若直接代理会劫持前端深链。Vite 只代理 /api 并 rewrite 去掉前缀，后端路径保持契约不变。
  const res = await fetch(`/api${path}`, { ...init, headers })
  if (res.status === 204) return undefined as T

  const text = await res.text()
  const data: unknown = text ? JSON.parse(text) : undefined

  if (!res.ok) {
    const error = (data as { error?: { code?: string; message?: string; details?: ApiError['details'] } })
      ?.error
    throw new ApiError(
      res.status,
      error?.code ?? 'UNKNOWN',
      error?.message ?? '请求失败',
      error?.details,
    )
  }
  return data as T
}

export function login(account: string, password: string) {
  return apiFetch<{ token: string; user: UserBrief }>('/auth/login', {
    method: 'POST',
    body: JSON.stringify({ account, password }),
  })
}

export function fetchMe() {
  return apiFetch<UserBrief>('/auth/me')
}

export function listProjects() {
  return apiFetch<{ items: ProjectView[] }>('/projects')

