.uml-dev-page { margin: 24px auto; max-width: 1440px; padding: 0 20px; color: #17263a; font-family: system-ui, sans-serif; }
.uml-dev-page h1 { font-size: 24px; }
.uml-editor { color: #17263a; }
.uml-notice { background: #edf4ff; border-left: 4px solid #4777b3; padding: 12px 16px; line-height: 1.7; }
.uml-workspace { display: grid; grid-template-columns: minmax(300px, 400px) minmax(0, 1fr); gap: 20px; align-items: start; }
.uml-controls { min-width: 0; }
.uml-fieldset { border: 1px solid #ccd5e1; border-radius: 8px; padding: 16px; margin: 0; min-width: 0; }
.uml-fieldset legend { font-weight: 700; }
.uml-fieldset h3 { font-size: 16px; margin: 20px 0 10px; }
.uml-fieldset label, .uml-transfer label { display: flex; flex-direction: column; gap: 5px; font-size: 14px; }
.uml-node-row { display: flex; gap: 8px; align-items: end; margin-bottom: 10px; }
.uml-node-row label { flex: 1; min-width: 0; }
.uml-node-actions { display: flex; flex-wrap: wrap; gap: 4px; max-width: 145px; }
.uml-node-actions button { padding: 6px 8px; font-size: 13px; }
.uml-editor input, .uml-editor select, .uml-transfer textarea { box-sizing: border-box; width: 100%; padding: 8px; border: 1px solid #a7b5c7; border-radius: 5px; background: white; color: #17263a; font: inherit; }
.uml-editor button, .uml-dev-page > .uml-actions button, .uml-transfer button { background: #fff; border: 1px solid #8197b2; border-radius: 5px; color: #17263a; padding: 7px 12px; cursor: pointer; font: inherit; }
.uml-editor button:disabled, .uml-dev-page button:disabled { opacity: .5; cursor: not-allowed; }
.uml-editor :focus-visible, .uml-dev-page :focus-visible { outline: 3px solid #75a7e5; outline-offset: 2px; }
.uml-dev-page button[aria-pressed="true"] { background: #174f89; color: white; }
.uml-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; margin: 12px 0; }
