.uml-errors { color: #8c2222; border-left: 4px solid #b34242; padding: 10px 14px; background: #fff3f3; overflow-wrap: anywhere; }
.uml-preview { overflow: auto; max-height: 780px; border: 1px solid #ccd5e1; border-radius: 8px; color: #243b57; background: #fff; }
