.uml-preview text { fill: currentColor; }
.uml-boundary { fill: #f8fbff; stroke: #a8bbd1; }
.uml-node { fill: #eaf2ff; stroke: #34618f; stroke-width: 1.5; }
.uml-actor { fill: white; stroke: currentColor; stroke-width: 1.5; }
.uml-edge { stroke: currentColor; stroke-width: 1.5; fill: none; }
.uml-dashed { stroke-dasharray: 6 4; }
.uml-edge-label { font-size: 12px; }
.uml-lifeline { stroke: #8799b2; stroke-dasharray: 5 5; }
.uml-transfer { margin: 24px 0; padding: 20px; background: #f7f9fc; border: 1px solid #ccd5e1; border-radius: 8px; }
.uml-transfer pre { overflow: auto; max-height: 260px; white-space: pre-wrap; overflow-wrap: anywhere; }
.uml-transfer textarea { margin: 6px 0 12px; font-family: monospace; }
@media (max-width: 850px) { .uml-workspace { grid-template-columns: minmax(0, 1fr); } .uml-preview { max-height: 500px; } .uml-dev-page { padding: 0 12px; } }

